import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-09-06","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-09-06","date":"2023-09-06T00:00:00.000Z","updated":"2023-10-04T00:00:00.000Z","tags":["Ceph","RGW重构","AWS SNS","主题策略","多站点通知复制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-09-06.md"};function a(n,l,s,p,g,u){return t(),e("div",null,[...l[0]||(l[0]=[o('<p>本次会议主要讨论了Ceph RGW的重构议题，包括以下几个方面：</p><h4 id="会议议题" tabindex="-1">会议议题 <a class="header-anchor" href="#会议议题" aria-label="Permalink to &quot;会议议题&quot;">​</a></h4><ol><li><p><strong>AWS SNS主题管理权限问题</strong></p><ul><li>讨论了AWS SNS主题管理权限的分配问题，指出当前任何用户都可以创建、更新或删除主题，这与SNS文档中的描述不符。</li><li>提出将主题与创建者用户关联，以确保只有创建者可以管理该主题。</li></ul></li><li><p><strong>多站点环境下的通知复制问题</strong></p><ul><li>讨论了在多站点环境中，通知未被复制到次要站点的问题，这是一个已知的bug。</li><li>提出将通知配置作为桶属性的可能性，以便通过现有的同步机制进行同步。</li></ul></li><li><p><strong>AWS CLI工具的改进</strong></p><ul><li>讨论了AWS CLI工具在获取和列出主题时应仅显示用户拥有的主题，而不是所有主题。</li><li>提出了匿名主题的概念，即未与特定用户关联的主题。</li></ul></li><li><p><strong>主题与桶的关联及权限管理</strong></p><ul><li>讨论了用户是否可以订阅其他用户创建的主题的问题。</li><li>提出了使用策略来管理主题的访问权限。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ol><li><p><strong>主题与用户关联</strong></p><ul><li>决定将主题与创建者用户关联，并考虑现有部署的兼容性问题。</li></ul></li><li><p><strong>多站点环境下的通知复制</strong></p><ul><li>确认了通知未被复制到次要站点的问题，并将继续跟踪和解决该问题。</li></ul></li><li><p><strong>AWS CLI工具改进</strong></p><ul><li>决定改进AWS CLI工具，使其仅显示用户拥有的主题。</li></ul></li><li><p><strong>主题与桶的关联及权限管理</strong></p><ul><li>决定探索使用策略来管理主题的访问权限。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>主题与用户关联</strong></p><ul><li>创建一个新的跟踪器，以继续讨论和实现主题与用户关联的功能。</li></ul></li><li><p><strong>多站点环境下的通知复制</strong></p><ul><li>继续跟踪和解决通知未被复制到次要站点的问题。</li></ul></li><li><p><strong>AWS CLI工具改进</strong></p><ul><li>改进AWS CLI工具，使其仅显示用户拥有的主题。</li></ul></li><li><p><strong>主题与桶的关联及权限管理</strong></p><ul><li>探索使用策略来管理主题的访问权限。</li></ul></li></ol><p>本次会议的讨论内容涵盖了Ceph RGW重构的多个关键方面，包括权限管理、多站点通知复制、CLI工具改进以及主题与桶的关联等问题，并制定了相应的后续行动计划。</p>',8)])])}const d=i(r,[["render",a]]);export{c as __pageData,d as default};
